import 'widget_scan.dart';

/// The generated file's path under `lib/`.
const String widgetNamesFileName = 'tugboat_widget_names.g.dart';

/// Renders the generated Dart source for [named].
///
/// The result depends only on the sets of widgets passed in, never on their
/// order: entries sort by class name then library URI, and each library's
/// import prefix comes from its position in the sorted URI list. [generic]
/// and [privateCount] only feed the explanatory comment.
String renderWidgetNames({
  required String variableName,
  required Iterable<WidgetClass> named,
  Iterable<WidgetClass> generic = const [],
  int privateCount = 0,
}) {
  final entries = named.toSet().toList()..sort();
  final uris = entries.map((entry) => entry.libraryUri).toSet().toList()
    ..sort();
  final prefixes = {for (var i = 0; i < uris.length; i++) uris[i]: '_i$i'};
  final buffer = StringBuffer()
    ..writeln('// GENERATED CODE - DO NOT MODIFY BY HAND')
    ..writeln('// Generated by tugboat_build. Regenerate with:')
    ..writeln('//   dart run build_runner build')
    ..writeln('//')
    ..writeln('// ignore_for_file: type=lint')
    ..writeln();
  for (final uri in uris) {
    buffer.writeln("import '${_escape(uri)}' as ${prefixes[uri]};");
  }
  if (uris.isNotEmpty) buffer.writeln();
  _writeSkipped(buffer, generic.toSet().toList()..sort(), privateCount);
  buffer
    ..writeln('/// Readable names of this package\'s widget classes, for')
    ..writeln('/// `TugboatReplayConfig(widgetNames: $variableName)`.')
    ..writeln('const Map<Type, String> $variableName = {');
  for (final entry in entries) {
    final key = '${prefixes[entry.libraryUri]}.${entry.name}';
    buffer.writeln("  $key: '${_escape(entry.name)}',");
  }
  buffer.writeln('};');
  return buffer.toString();
}

void _writeSkipped(
  StringBuffer buffer,
  List<WidgetClass> generic,
  int privateCount,
) {
  if (generic.isEmpty && privateCount == 0) return;
  buffer.writeln('// Widgets that cannot be named here:');
  if (privateCount > 0) {
    buffer.writeln('// - $privateCount private (leading underscore)');
  }
  for (final entry in generic) {
    buffer.writeln('// - ${entry.name} (generic), ${entry.libraryUri}');
  }
  buffer.writeln();
}

/// Escapes [value] for a single-quoted Dart string literal. Class names may
/// contain `$`, which would otherwise start an interpolation.
String _escape(String value) => value
    .replaceAll(r'\', r'\\')
    .replaceAll("'", r"\'")
    .replaceAll(r'$', r'\$');
